import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { alias: { "@": resolve(".") } });
const policy = await jiti.import(resolve("lib/ai/evidence-policy.ts"));
const contacts = await jiti.import(resolve("lib/ai/contact-intelligence.ts"));
const customerAnalysis = await jiti.import(resolve("lib/ai/customer-analysis.ts"));
const runner = await jiti.import(resolve("lib/ai/run-customer-analysis.ts"));
const web = await jiti.import(resolve("lib/ai/web-enrichment.ts"));
const errors = await jiti.import(resolve("lib/ai/error-normalization.ts"));
const source = (file) => readFileSync(resolve(file), "utf8");
let passed = 0;
const test = (name, fn) => { fn(); passed += 1; process.stdout.write(`✓ ${name}\n`); };
const evidence = (fact, kind="支持", channel="website", url="https://shop.example.com/services/repair") => ({ sourceId:`S${passed}`, channel, sourceUrl:url, fact, kind, confidence:96 });
const gate = (overrides={}) => policy.evaluateEvidenceGate({ strategy:"SMART", identityStatus:"MATCHED", identityConfidence:96, industryConfidence:96, decisionConfidence:96, score:82, industry:"MOBILE_PHONE_REPAIR_SHOP", evidence:[evidence("官网明确提供手机换屏和电池更换服务")], hasCriticalConflict:false, ...overrides });

test("01 只卖手机成品不判维修店",()=>assert.equal(policy.primaryIndustryFor("手机成品零售"),"MOBILE_PHONE_RETAILER"));
test("02 运营商营业厅单独分类",()=>assert.equal(policy.primaryIndustryFor("运营商营业厅"),"MOBILE_NETWORK_OPERATOR_STORE"));
test("03 外配件零售与内配件分离",()=>assert.equal(policy.primaryIndustryFor("手机外配件零售"),"MOBILE_ACCESSORY_RETAILER"));
test("04 维修店不自动映射批发商",()=>assert.notEqual(policy.primaryIndustryFor("手机维修店"),"MOBILE_REPAIR_PARTS_WHOLESALER"));
test("05 普通电脑维修与Apple维修分离",()=>assert.notEqual(policy.primaryIndustryFor("电脑维修店"),"APPLE_DEVICE_REPAIR_SHOP"));
test("06 明确换屏换电池是强直接证据",()=>assert.equal(policy.evidenceStrengthFor(evidence("官网明确提供手机换屏和电池更换服务")),"STRONG_DIRECT"));
test("07 只有原始标签归UNKNOWN",()=>assert.equal(policy.primaryIndustryFor("其他"),"UNKNOWN"));
test("08 无外部证据不得自动开发",()=>assert.equal(gate({evidence:[]}).automationStatus,"AUTO_HOLD"));
test("09 Google候选按匹配分排序而非首条",()=>assert.match(source("lib/ai/web-enrichment.ts"),/details\.map[\s\S]*sort\(\(a, b\) => b\.score - a\.score\)/));
test("10 社媒登录页不能成为证据",()=>assert.match(source("lib/ai/web-enrichment.ts"),/社媒登录页或Cookie页/));
test("11 官网新电话可标准化",()=>assert.equal(contacts.normalizePhoneInternational("020 7946 0958","GB"),"+442079460958"));
test("12 地图国际电话保持E164",()=>assert.equal(contacts.normalizePhoneInternational("+34 641 58 19 81","ES"),"+34641581981"));
test("13 新电话不覆盖原值而标记新增",()=>assert.equal(contacts.buildContactCandidate({type:"PHONE",value:"+34641581981",country:"ES",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:["+34600000000"]}).verificationStatus,"NEW_VERIFIED"));
test("14 官网地图多个官方电话均保留来源",()=>{const a=contacts.buildContactCandidate({type:"PHONE",value:"+34611111111",country:"ES",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:[]});const b=contacts.buildContactCandidate({type:"PHONE",value:"+34622222222",country:"ES",sourceChannel:"google_maps",sourceUrl:"https://google.com/maps/place/a",identityStatus:"MATCHED",originalValues:[]});const r=contacts.reconcileContacts([a,b]);assert.equal(r.contacts.length,2);assert.ok(r.contacts.every(x=>x.verificationStatus==="NEW_VERIFIED"));});
test("14B 未核实候选联系方式不得成为推荐联系方式",()=>{const item=contacts.buildContactCandidate({type:"PHONE",value:"+35312447391",country:"IE",sourceChannel:"google_maps",sourceUrl:"https://google.com/maps/search/wrong",identityStatus:"AMBIGUOUS",originalValues:[]});const r=contacts.reconcileContacts([item]);assert.equal(item.verificationStatus,"UNVERIFIED");assert.equal(r.preferred,null);});
test("15 总部与分店按来源URL分开保存",()=>assert.match(source("lib/ai/contact-intelligence.ts"),/valueNormalized\}\|\$\{candidate\.sourceUrl/));
test("16 新邮箱记录准确来源",()=>assert.equal(contacts.buildContactCandidate({type:"EMAIL",value:"sales@a.es",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:[]}).sourceUrl,"https://a.es/contact"));
test("17 示例邮箱被拒绝",()=>assert.equal(contacts.normalizeEmailStrict("sales@example.com"),""));
test("18 普通电话不自动判WhatsApp",()=>assert.match(source("lib/ai/web-enrichment.ts"),/extractWhatsapps/));
test("19 依据页显眼显示新联系方式",()=>assert.match(source("components/ai-screening/evidence-view.tsx"),/VerifiedContactsSection/));
test("20 状态同时有文字和图标",()=>{const s=source("components/ai-screening/evidence-sections.tsx");assert.match(s,/新发现并已核实/);assert.match(s,/CheckCircle2/);});
test("21 联系方式支持复制和来源链接",()=>{const s=source("components/ai-screening/evidence-sections.tsx");assert.match(s,/navigator\.clipboard\.writeText/);assert.match(s,/核对来源/);});
test("22 缓存复用保留原证据时间",()=>assert.match(source("lib/ai/run-customer-analysis.ts"),/captured_at: source\.captured_at \|\| source\.fetched_at \|\| cache\.original_captured_at/));
test("23 客户数据变化使缓存签名变化",()=>{const s=source("lib/ai/reuse-cache.ts");for(const field of ["company_name","phone","email","website","google_url","linkedin_url","facebook_url","instagram_url"])assert.match(s,new RegExp(field));assert.match(s,/source_signature/);});
test("24 海关同名不得直接归属",()=>assert.match(source("lib/ai/customer-analysis.ts"),/身份匹配的海关记录/));
test("25 海关查询不得阻塞基础分析",()=>assert.doesNotMatch(source("lib/ai/run-customer-analysis.ts"),/await\s+collectCustoms/));
test("26 智能模式不逐渠道调用模型",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/run\("all_available_sources"/);assert.match(s,/run\("all_available_sources_retry"/);});
test("27 深度模式单条强直接证据可完成行业判断",()=>assert.equal(gate({strategy:"DEEP"}).automationStatus,"AUTO_DEVELOP"));
test("28 暂停继续跳过已完成客户",()=>assert.match(source("workflows/ai-screening.ts"),/\.eq\("status", "PENDING"\)/));
test("29 报告数据来自数据库结果",()=>assert.match(source("app/api/ai/results/route.ts"),/ai_screening_results/));
test("30 无证据VALID为0",()=>assert.notEqual(policy.compatibilityTargetDecision(gate({evidence:[]}).automationStatus),"VALID"));
test("31 无证据INVALID为0",()=>assert.notEqual(policy.compatibilityTargetDecision(gate({evidence:[]}).automationStatus),"INVALID"));
test("32 Google维修分类只是需要佐证的定位线索",()=>assert.equal(policy.evidenceStrengthFor(evidence("Google商家页明确分类为手机维修店","支持","google_maps","https://www.google.com/maps/place/demo")),"MEDIUM_CORROBORATING"));
test("33 不再存在整客户30秒硬超时",()=>{const runner=source("lib/ai/run-customer-analysis.ts");const workflow=source("workflows/ai-screening.ts");assert.doesNotMatch(runner,/timeoutController\.abort\(\), 30_000/);assert.doesNotMatch(workflow,/Promise\.race\(\[analysis, deadline\]\)/);});
test("34 单一Google维修分类不得自动评级",()=>{const result=customerAnalysis.groundCustomerAnalysis({customer_name:"测试维修店",country:"EC",google_url:"https://www.google.com/maps/place/test",evidence:{google_place:{configured:false,name:"测试维修店",types:["手机维修店"],reviews:[],identity_status:"MATCHED",identity_confidence:96,business_status:"OPERATIONAL",verified_google_maps_url:"https://www.google.com/maps/place/test"}}},{industry_type:"手机维修店",is_target_customer:true,ai_score:88,ai_level:"A",ai_reason:"公开信息显示该商家提供手机维修服务。",business_relevance:"提供手机维修服务。",customer_value:"可能采购手机维修配件。",followup_suggestion:"联系确认配件需求。",confidence_score:95,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:95,company_authenticity:90,business_activity:90,mobile_parts_match:90,macbook_parts_match:0,wholesale_import_distribution:20,repair_business_match:95,bulk_purchase_potential:60,contactability:80,evidence_completeness:75,contradiction_risk:0},suggested_contact_order:[],evidence_summaries:[]});assert.equal(result.is_target_customer,false);assert.equal(result.ai_level,"D");assert.ok(result.ai_score<60);});
test("35 单一Google维修分类不得由规则引擎强行完成",()=>{const result=runner.deterministicAnalysis({id:"c1",company_name:"Phone Fix",country:"ES",google_url:"https://www.google.com/maps/place/phone-fix"},[{channel:"google_maps",status:"COLLECTED",source_url:"https://www.google.com/maps/place/phone-fix",evidence:{configured:false,name:"Phone Fix",types:["mobile phone repair shop"],reviews:[],identity_status:"MATCHED",identity_confidence:96,verified_google_maps_url:"https://www.google.com/maps/place/phone-fix"}}]);assert.equal(result,null);});
test("36 PostgREST对象错误不会退化为object Object",()=>{const result=errors.normalizeError({code:"PGRST204",message:"schema cache缺少字段",details:"column missing",hint:"reload"},{stage:"CUSTOMER_WRITEBACK"});assert.equal(result.error_code,"PGRST204");assert.match(result.error_message,/schema cache/);assert.doesNotMatch(result.error_message,/object Object/);});
test("37 证据与客户写回成功后才原子完成",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/is_latest_valid: false,[\s\S]*writeback_status: "PENDING"/);assert.match(s,/ai_screening_evidence[\s\S]*customers[\s\S]*writeback_status: "COMPLETED"/);assert.doesNotMatch(s,/status: "COMPLETED", analysis_status: "COMPLETED", writeback_status: "PENDING"/);});
test("38 任务统计以模型调用表为费用真值",()=>assert.match(source("supabase/migrations/202608240003_ai_screening_pipeline_v3.sql"),/case when c\.call_count > 0 then c\.total_cost_usd/));
test("39 模型内置网页搜索不再默认启用",()=>assert.doesNotMatch(source("lib/ai/customer-analysis.ts"),/tools:\s*\[\{ type: "web_search"/));
test("40 智能模式单次调用且深度模式最多两次",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/AI_SCREENING_DEEP_MAX_MODEL_CALLS_PER_CUSTOMER/);assert.match(s,/maxRequests: 1/);});
test("41 余额耗尽属于不可重试错误",()=>assert.equal(errors.normalizeError({status:429,code:"credit_balance_exhausted",message:"余额不足"},{stage:"MODEL_CALL"}).retryable,false));
test("42 智能模式输入证据有严格长度上限",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://a.example",evidence:{url:"https://a.example",reachable:true,title:"测试企业",description:"业务".repeat(1000),headings:Array(20).fill("手机维修"),text_excerpt:"维修换屏".repeat(4000),image_alts:Array(20).fill("维修门店"),image_urls:Array(20).fill("https://a.example/image.jpg"),video_urls:Array(10).fill("https://a.example/video.mp4"),emails:[],phones:[],pages:Array(8).fill({url:"https://a.example/service",title:"服务",description:"维修".repeat(500),headings:["维修"],text_excerpt:"换屏".repeat(1000),image_alts:[],image_urls:[],emails:[],phones:[]})}}],"fast");assert.ok(JSON.stringify(compact).length<7000);});
test("43 只发送少量关键图片且不发送视频给模型",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://a.example",evidence:{url:"https://a.example",reachable:true,headings:[],image_alts:[],image_urls:["https://a.example/image.jpg","https://a.example/image-2.jpg","https://a.example/image-3.jpg"],video_urls:["https://a.example/video.mp4"],emails:[],phones:[]}}],"deep");const text=JSON.stringify(compact);assert.match(text,/image\.jpg/);assert.match(text,/image-2\.jpg/);assert.doesNotMatch(text,/image-3\.jpg|video\.mp4/);});
test("44 无目标经营事实也必须完成筛选并保存低优先级评分",()=>{const result=runner.insufficientDataAnalysis({id:"low",company_name:"Unknown Company",country:"DE",phone:"+4912345"},[{channel:"website",status:"FAILED",source_url:"https://unknown.example",error:"无法读取"}]);assert.equal(result.ai_level,"D");assert.ok(result.ai_score>=0&&result.ai_score<60);assert.equal(result.evidence_sufficiency,"一般");assert.doesNotMatch(result.ai_reason,/资料不足|不评级|不打分/);const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/score: analysis\.ai_score, grade: analysis\.ai_level/);assert.match(s,/ai_score: analysis\.ai_score, ai_level: analysis\.ai_level/);assert.match(s,/ai_screening_done: true/);});
test("45 默认模型采用低成本分层",()=>{const s=source("lib/ai/customer-analysis.ts");assert.match(s,/gpt-5\.4-nano/);assert.match(s,/gpt-5\.4-mini/);assert.match(s,/gpt-5\.6-luna/);});
test("46 深度模式默认仅一次模型调用",()=>assert.match(source("lib/ai/run-customer-analysis.ts"),/AI_SCREENING_DEEP_MAX_MODEL_CALLS_PER_CUSTOMER \|\| 1/));
test("47 Google中文维修分类也必须有直接经营佐证",()=>{const result=runner.deterministicAnalysis({id:"c2",company_name:"测试手机维修",country:"PL",google_url:"https://www.google.com/maps/place/test"},[{channel:"google_maps",status:"COLLECTED",source_url:"https://www.google.com/maps/place/test",evidence:{configured:false,name:"测试手机维修",types:["手机维修店","手机配件商店"],reviews:[],identity_status:"MATCHED",identity_confidence:96,verified_google_maps_url:"https://www.google.com/maps/place/test"}}]);assert.equal(result,null);});
test("48 波兰语官网维修说明由规则引擎识别",()=>{const result=runner.deterministicAnalysis({id:"c3",company_name:"MedicPhone",country:"波兰",website:"https://medicphone.pl"},[{channel:"website",status:"COLLECTED",source_url:"https://medicphone.pl",evidence:{url:"https://medicphone.pl",reachable:true,title:"Naprawa i serwis telefonów Warszawa",description:"Profesjonalna naprawa telefonów i wymiana baterii",headings:[],text_excerpt:"",image_alts:[],image_urls:[],emails:[],phones:[]}}]);assert.equal(result.usage.total_tokens,0);assert.equal(result.industry_type,"手机维修店");assert.match(result.evidence_summaries[0].fact_zh,/企业官网/);});
test("51 企业邮箱域名仅用于补全官网入口，不作为行业证据",()=>{const runnerSource=source("lib/ai/run-customer-analysis.ts");assert.match(runnerSource,/function effectiveWebsite/);assert.match(runnerSource,/PERSONAL_EMAIL_DOMAINS/);assert.match(runnerSource,/it is never itself treated as proof/);});
test("52 官网联系方式保存不依赖可选唯一约束",()=>{const runnerSource=source("lib/ai/run-customer-analysis.ts");assert.doesNotMatch(runnerSource,/customer_contacts"\)\.upsert\(rows/);assert.match(runnerSource,/update\(row\)\.eq\("id", match\.id\)/);});
test("53 结构化输出上限足以容纳完整严格JSON",()=>{const analysis=source("lib/ai/customer-analysis.ts");assert.match(analysis,/\? 2400 : options\.tier === "deep" \? 2200 : 1800/);});
test("49 具体Google商家页缺少旧端点时回退精确名称搜索",()=>{const s=source("lib/ai/web-enrichment.ts");assert.match(s,/if \(!endpointMatch && isSpecificPlaceUrl\)/);assert.match(s,/canonicalSearchPage/);assert.match(s,/exactPlaceUrlScore/);});
test("50 模型JSON失败仍保留真实用量诊断",()=>{const analysis=source("lib/ai/customer-analysis.ts");const runnerSource=source("lib/ai/run-customer-analysis.ts");assert.match(analysis,/failure\.usage = usage/);assert.match(analysis,/max_output_tokens:[\s\S]*1800/);assert.match(runnerSource,/errorUsage/);});
test("54 成功任务写回空错误上下文而不是NULL",()=>{const runnerSource=source("lib/ai/run-customer-analysis.ts");assert.match(runnerSource,/error_context: writebackWarnings\.length \? \{ writeback_warnings: writebackWarnings \} : \{\}/);});
test("55 中文国家名称下同一波兰电话必须去重",()=>{const candidate=contacts.buildContactCandidate({type:"PHONE",value:"+48 91 317 72 00",country:"波兰",sourceChannel:"google_maps",sourceUrl:"https://www.google.com/maps/place/tel-kom",identityStatus:"MATCHED",originalValues:["48913177200"]});assert.equal(candidate?.valueNormalized,"+48913177200");assert.equal(candidate?.verificationStatus,"MATCHED_ORIGINAL");});
test("56 同一行业必须随证据质量变化而非固定分",()=>{const basic=runner.deterministicAnalysis({id:"score-1",company_name:"Serwis GSM",country:"波兰",google_url:"https://www.google.com/maps/place/serwis"},[{channel:"google_maps",status:"COLLECTED",source_url:"https://www.google.com/maps/place/serwis",evidence:{configured:false,name:"Serwis GSM",types:["手机维修店"],reviews:[],identity_status:"MATCHED",identity_confidence:80,verified_google_maps_url:"https://www.google.com/maps/place/serwis"}}]);const strong=runner.deterministicAnalysis({id:"score-2",company_name:"Serwis GSM",country:"波兰",phone:"+48913177200",email:"info@serwis.pl",website:"https://serwis.pl",google_url:"https://www.google.com/maps/place/serwis"},[{channel:"google_maps",status:"COLLECTED",source_url:"https://www.google.com/maps/place/serwis",evidence:{configured:false,name:"Serwis GSM",types:["手机维修店"],reviews:["客户确认更换iPhone屏幕和电池"],user_ratings_total:120,identity_status:"MATCHED",identity_confidence:98,verified_google_maps_url:"https://www.google.com/maps/place/serwis"}},{channel:"website",status:"COLLECTED",source_url:"https://serwis.pl",evidence:{url:"https://serwis.pl",reachable:true,title:"Serwis GSM",description:"Naprawa telefonów, wymiana baterii iPhone",headings:["Naprawa telefonów"],text_excerpt:"Wymiana baterii iPhone i screen replacement",image_alts:[],image_urls:[],emails:["info@serwis.pl"],phones:["+48913177200"]}}]);assert.equal(basic,null);assert.ok(strong);assert.equal(strong.ai_level,"A");assert.ok(strong.ai_score>=85);});
test("57 波兰Apple设备维修变体可零Token识别",()=>{const result=runner.deterministicAnalysis({id:"pl-apple",company_name:"HiApple",country:"波兰",website:"https://hiapple.pl"},[{channel:"website",status:"COLLECTED",source_url:"https://hiapple.pl",evidence:{url:"https://hiapple.pl",reachable:true,title:"Pogwarancyjny Serwis Apple",description:"Serwis sprzętu Apple i naprawa urządzeń iPhone, iPad i MacBook",headings:[],text_excerpt:"",image_alts:[],image_urls:[],emails:[],phones:[]}}]);assert.equal(result?.usage.total_tokens,0);assert.equal(result?.industry_type,"Apple或MacBook维修店");});
test("58 任意语种结构化业务描述会送入压缩模型证据",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://a.example",evidence:{url:"https://a.example",reachable:true,language:"ja",title:"修理サービス",description:"",structured_types:["LocalBusiness"],structured_names:["例商店"],structured_descriptions:["携帯電話とパソコンの修理サービス"],headings:[],text_excerpt:"",image_alts:[],image_urls:[],emails:[],phones:[]}}],"fast");assert.equal(compact.website?.language,"ja");assert.deepEqual(compact.website?.structured_descriptions,["携帯電話とパソコンの修理サービス"]);});
test("59 JSON截断属于可恢复错误",()=>assert.equal(errors.normalizeError(new Error("OPENAI_INVALID_JSON"),{stage:"MODEL_CALL"}).retryable,true));
test("61 任意语种页面保留语言与原文结构化证据",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://repair.example.jp",evidence:{url:"https://repair.example.jp",reachable:true,language:"ja-JP",title:"携帯電話修理",description:"画面交換とバッテリー交換",structured_types:["LocalBusiness"],structured_names:["修理店"],structured_descriptions:["iPhoneとパソコンの修理サービス"],headings:[],text_excerpt:"即日修理",image_alts:[],image_urls:[],emails:[],phones:[]}}],"fast");assert.equal(compact.website?.language,"ja-JP");assert.match(compact.website?.text_excerpt||"",/即日修理/);});
test("60 具体官网域名主体匹配不再被弱名称信号否决",()=>assert.match(source("lib/ai/run-customer-analysis.ts"),/Math\.max\(providedDomainMatch \? 75 : 0/));
